phase(thought,sheet.getBoundingClientRect().top<innerHeight*.26?'organize':'open');
const p=innerHeight-host.getBoundingClientRect().top;
phase(prompt,p<innerHeight*.42?'orb':p<innerHeight*.82?'capsule':'board');

